def build_css_style():
 css=':root{--bg:#0d1117;--card:#161b22;--border:#30363d;--text:#c9d1d9;--blue:#58a6ff;--green:#3fb950;--orange:#d2991d;--red:#f85149;--muted:#8b949e}body{font-family:system-ui,sans-serif;background:var(--bg);color:var(--text);margin:0;padding:0;line-height:1.6}.console-header{background:var(--card);border-bottom:1px solid var(--border);padding:20px 24px;text-align:center}.console-header h1{color:var(--blue);margin:0}.status-bar{display:flex;justify-content:center;gap:16px;margin-top:8px;font-size:13px;color:var(--muted)}.nav-bar{display:flex;justify-content:center;gap:12px;padding:12px;background:var(--card);border-bottom:1px solid var(--border);position:sticky;top:0;z-index:10}.nav-bar a{color:var(--blue);text-decoration:none;font-size:13px;padding:4px 8px;border-radius:4px}.nav-bar a:hover{background:var(--border)}.console-main{max-width:1200px;margin:0 auto;padding:24px}section{margin-bottom:32px}section h2{font-size:18px;color:var(--blue);border-bottom:1px solid var(--border);padding-bottom:8px;margin-bottom:16px}.ticker-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:16px}.ticker-card{background:var(--card);border:1px solid var(--border);border-radius:8px;padding:16px}.ticker-card.CN_A{border-left:3px solid var(--red)}.ticker-card.HK{border-left:3px solid var(--orange)}.ticker-card.US{border-left:3px solid var(--blue)}.ticker-card h3{margin:0 0 4px 0;font-size:15px}.ticker-card .meta{font-size:12px;color:var(--muted)}.ticker-card .thesis{font-size:13px;margin-top:8px}.high{color:var(--green)}.medium{color:var(--orange)}.low{color:var(--red)}.thesis-list{display:flex;flex-direction:column;gap:12px}.thesis-item{background:var(--card);border:1px solid var(--border);border-radius:8px;padding:14px}.info-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px}.info-card{background:var(--card);border:1px solid var(--border);border-radius:8px;padding:14px}.info-card h4{margin:0 0 4px 0;font-size:14px;color:var(--blue)}.info-card p,.info-card li{font-size:13px}.info-card ul{padding-left:16px;margin:4px 0 0 0}.console-footer{text-align:center;padding:20px;font-size:12px;color:var(--muted);border-top:1px solid var(--border)}.tag{display:inline-block;padding:2px 6px;border-radius:3px;font-size:11px;margin-right:4px}.tag-pass{background:var(--green);color:#000}.tag-warn{background:var(--orange);color:#000}.tag-info{background:var(--blue);color:#000}'
 return {'phase141_css_style_builder':{'css':css,'ready':True,'mock_used':False,'fixture_used':False}}
